<?php
require_once 'config/database.php';require_once 'includes/functions.php';$id=(int)($_GET['id']??0);
$s=$pdo->prepare("SELECT j.*,c.name category_name,p.full_name,p.user_id employer_id FROM jobs j JOIN categories c ON c.id=j.category_id JOIN profiles p ON p.user_id=j.user_id WHERE j.id=?");$s->execute([$id]);$j=$s->fetch();if(!$j){http_response_code(404);exit('Job not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'&&is_logged_in()){verify_csrf();$cover=trim($_POST['cover_letter']);if($cover){$q=$pdo->prepare("INSERT INTO applications(job_id,user_id,cover_letter) VALUES(?,?,?)");try{$q->execute([$id,current_user_id(),$cover]);flash('success','Application submitted.');}catch(PDOException $e){flash('error','You have already applied or cannot apply to this job.');}redirect('job.php?id='.$id);}}
$pageTitle=$j['title'];include 'includes/header.php';?>
<section class="section"><div class="container narrow"><div class="job-detail"><span class="tag"><?=e($j['category_name'])?></span><h1><?=e($j['title'])?></h1><div class="meta big"><span>📍 <?=e($j['location'])?></span><span>💰 <?=e(money_range($j['budget_min'],$j['budget_max'],$j['currency']))?></span></div><hr><p class="description"><?=nl2br(e($j['description']))?></p><p class="muted">Posted by <?=e($j['full_name'])?></p>
<?php if(is_logged_in() && current_user_id()!==$j['employer_id']):?><form method="post" class="apply-box"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Apply for this job</h2><textarea name="cover_letter" rows="6" required placeholder="Tell the client why you are a good fit..."></textarea><button class="btn">Send application</button></form><?php elseif(!is_logged_in()):?><div class="apply-box"><h2>Interested?</h2><p>Create a free account to apply for this job.</p><a class="btn" href="register.php">Create account</a></div><?php endif;?></div></div></section><?php include 'includes/footer.php';?>
